{"file_path":"tests/test_spec.py","content":""""Behavioral checks for each section of SPEC.md."""

import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


# Section 1

def test_monitor_flag_rate_none_counts_in_denominator():
    assert monitor_flag_rate([event("a", 1, True), event("b", 1, None),
                              event("c", 1, False)]) == 1 / 3
    assert monitor_flag_rate([event("a", 1, None)]) == 0.0
    assert monitor_flag_rate([]) == 0.0


# Section 2

def test_pooled_flag_rate_weights_transcripts_and_handles_empty():
    groups = {"a": [event("a", 1, True)],
              "b": [event("b", 1, False), event("c", 1, None), event("d", 1, False)],
              "empty": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({"empty": []}) == 0.0
    assert pooled_flag_rate({}) == 0.0


# Section 3

@pytest.mark.parametrize("days, expected", [(0, 0), (1, 3), (2, 5), (3, 6), (5, 6)])
def test_flags_in_window(days, expected):
    assert flags_in_window([1, 2, 3], days) == expected
    assert flags_in_window([], days) == 0


# Section 4

def test_parse_transcript_log_fields_and_skipped_lines():
    lines = ["\n", "   ", "  # comment,with,commas", "  x  , -2 , 1  ",
             "y, 3, 0", " z , 4 ,   "]
    assert parse_transcript_log(lines) == [event("x", -2, True), event("y", 3, False),
                                           event("z", 4, None)]


@pytest.mark.parametrize("bad_line", ["only,two", "too,many,fields,here", "x,no-day,1"])
def test_parse_transcript_log_error_line_numbers_include_skipped(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["", " # skipped", "ok,1,0", bad_line])


def test_parse_transcript_log_invalid_flag():
    with pytest.raises(ValueError, match=r"line 1\b"):
        parse_transcript_log(["x,1,true"])


# Section 5

def test_dedupe_transcripts_last_duplicate_wins_and_result_sorted():
    events = [event("x", 10, True), event("b", 2, True), event("a", 2, False),
              event("x", 1, None), event("b", 2, False)]
    assert dedupe_transcripts(events) == [events[3], events[2], events[4]]
    assert dedupe_transcripts([]) == []


# Section 6

def test_daily_flag_counts_inclusive_range_and_gaps():
    events = [event("a", 1, True), event("b", 1, True), event("c", 2, None),
              event("d", 3, False), event("e", 4, True), event("f", 5, True)]
    assert daily_flag_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_flag_counts(events, 2, 2) == [0]
    assert daily_flag_counts([], 1, 3) == [0, 0, 0]
    assert daily_flag_counts(events, 4, 1) == []


# Section 7

def test_monitor_summary_uses_calendar_days_pooled_rate_and_nonempty_groups():
    groups = {"a": [event("a", 1, True)], "b": [event("b", 4, True),
              event("c", 4, False), event("d", 4, None)], "empty": []}
    assert monitor_summary(groups, 3) == {"rate": 0.5, "recent": 1, "groups": 2}
    assert monitor_summary(groups, 0) == {"rate": 0.5, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 9) == {"rate": 0.5, "recent": 2, "groups": 2}
    assert monitor_summary({"empty": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert monitor_summary({}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert monitor_summary({"a": [event("x", 1, True), event("y", 1, False),
                                  event("z", 1, False)]}, 1)["rate"] == 0.333


# Section 8

def test_top_flagged_groups_ranking_ties_and_empty():
    groups = {"z": [event("a", 1, True)], "empty": [], "b": [event("b", 1, False)],
              "a": [event("c", 1, True)], "c": [event("d", 1, None)]}
    assert top_flagged_groups(groups, 3) == ["a", "z", "b"]
    assert top_flagged_groups(groups, 10) == ["a", "z", "b", "c"]
    assert top_flagged_groups(groups, 0) == []
    assert top_flagged_groups({}, 1) == []


# Section 9

def test_flag_rate_by_group_sorted_and_empty_none():
    groups = {"z": [], "b": [event("b", 1, None)],
              "a": [event("a", 1, True), event("c", 1, False)]}
    result = flag_rate_by_group(groups)
    assert list(result.items()) == [("a", 0.5), ("b", 0.0), ("z", None)]
    assert flag_rate_by_group({}) == {}


# Section 10

def test_longest_flag_streak_resets_and_ignores_nonpositive():
    assert longest_flag_streak([1, 2, 0, 3, -1, 4, 5, 6, 0, 7]) == 3
    assert longest_flag_streak([0, -1, 0]) == 0
    assert longest_flag_streak([]) == 0
